/* ============================================================
   XI.E — Recovery from Unusual Flight Attitudes
   Spine: nose-high = Power-Pitch-Bank (avoid a stall) · nose-low = Power-Bank-Pitch (avoid overstress)
   ============================================================ */
window.CFI_SCRIPTS['xi-e-unusual-attitudes'] = { nodes: [
  S('Introduction'),
  H('Attention'),
  P('An unusual attitude is never something you plan for — train the recovery until it\'s a reflex, not a decision.'),
  H('Overview'),
  P('Why UAs are dangerous — instinctive, not deliberate, reactions'),
  P('What causes unusual attitudes — environmental, mechanical, human'),
  P('Recognizing nose-high vs nose-low from the instruments'),
  P('Recovery basics & operating-envelope considerations'),
  P('Recovery — nose-high (avoid a stall) and nose-low (avoid overstress)'),
  P('Coordination during recovery'),
  P('Common errors'),
  P('RM: inadvertent IMC, collision, terrain, distractions/SA'),
  H('What'),
  P('Getting the airplane back to straight-and-level as fast and safely as possible — not diagnosing how it got there.'),
  H('Why'),
  B('Untrained pilots react to a UA instinctively, and instinct is usually wrong — training makes the correct response automatic instead of a guess made under startle.'),

  S('How:'),

  P('Unusual attitudes are unexpected, not intentional — the reaction is instinctive and often dangerous rather than deliberate.'),
  P('The immediate problem is never how you got there — it\'s what the airplane is doing now and how to get back to straight-and-level fast and safely.'),

  H('Unusual Attitude Situations — AI.XI.E.R1/R3'),
  P('Turbulence, preoccupation with flight-deck duties, disorientation, task saturation, instrument failure, crosscheck errors, stress, or a control-input error can all put the airplane somewhere you didn\'t intend.'),

  H('Preventing Unusual Attitudes — AI.XI.E.K1'),
  A('Environmental'),
  P('Turbulence and sudden wind shifts (clear-air turbulence, mountain waves, wind shear, thunderstorms, microbursts) — avoid the weather with preflight planning, reports, PIREPs.'),
  A('Mechanical'),
  P('Mechanical failures — asymmetric flaps, a malfunctioning control, runaway trim — can cause a departure from normal flight on their own.'),
  P('Instrument or autopilot failure, or a runaway trim/control malfunction — an autopilot fault can be insidious, so disengage it and fly the airplane if something feels off.', 3),
  P('Know the systems and POH procedures well enough to prevent the failure from becoming a UA.', 3),
  A('Human'),
  P('VMC-to-IMC loses the natural horizon, inviting disorientation · divided attention or task saturation narrows the margin between demand and capability · fixation parks the crosscheck on one instrument · sensory overload/deprivation makes warnings hard to sort.'),
  A('Spatial disorientation'),
  P('A significant factor in upset accidents — recognized (caught and corrected) · unrecognized (unaware, no correction) · incapacitating (can\'t process it, lacks the skill, or it exceeds ability) — training and practice move a pilot toward "recognized."'),
  B('Flying by feel instead of the instruments leads almost always to the wrong correction.'),
  P('Surprise (violates expectations) and startle (the involuntary reflex) hit untrained pilots hardest — "we don\'t rise to our expectations, we fall to our training." BAI skills fade without practice.', 3),
  P('See II.A. Human Factors for more on illusions and spatial disorientation.', 3),

  S('RM: Recognizing Unusual Attitudes — AI.XI.E.R2'),
  B('Any instrument rate or indication outside a normal maneuver means: assume a UA and accelerate the crosscheck to confirm it.'),
  P('Two categories: nose-high and nose-low attitudes.'),
  A('Nose-high (climbing turn)'),
  P('Airspeed decreasing, altimeter/VSI increasing (positive rate), turn coordinator may show a bank, attitude indicator nose high with a lot of blue.'),
  A('Nose-low (diving spiral)'),
  P('Same instruments, opposite directions — airspeed increasing, altitude/VSI decreasing (negative rate), attitude indicator nose low with a lot of brown.'),

  H('RM: Recovery Basics — AI.XI.E.K2/R6'),
  P('Recover without the attitude indicator on analog panels: if spillable its limits may be exceeded, even a working one can be off 5° pitch/bank, it may be inoperative (possibly why the UA happened), and it\'s hard to interpret at extreme attitudes.'),
  P('Recovery instead uses the airspeed indicator, altimeter, VSI, and turn coordinator; follow the POH if it differs. A glass-panel attitude indicator is reliable for recovery.', 3),
  A('Nose-high vs nose-low intent'),
  P('The procedures look similar but differ — nose-high recovery prevents a stall; nose-low recovery prevents overstressing the airplane.'),

  H('Nose-High (Climbing Turn) Recovery — AI.XI.E.K2'),
  B('Power — Pitch — Bank, nearly simultaneously.'),
  P('Power: add as needed, proportional to the deceleration. Pitch: forward elevator to lower the nose and reduce AOA, preventing the stall. Bank: coordinated aileron/rudder to level the wings.'),
  A('Verify the recovery'),
  P('As the altimeter and airspeed needles slow, level flight is close; when they stop and reverse, you\'re passing through level. Return to altitude, confirm level/coordinated, set power for the desired airspeed.'),

  H('Nose-Low (Diving Spiral) Recovery — AI.XI.E.K2'),
  B('Power — Bank — Pitch, all together.'),
  P('Power: reduce to prevent excess airspeed and altitude loss. Bank: level the wings first — leveling before raising the nose cuts G load. Pitch: smoothly raise the nose for level flight.'),
  P('If ground contact is a concern, use whatever back pressure is necessary to survive.', 3),
  P('All three change together for a smooth recovery, then verify the same way — needles slowing and reversing means passing through level; confirm level/coordinated, set power for the desired airspeed.'),

  H('Coordination During Recovery'),
  P('Use the turn coordinator (and attitude indicator, if available) throughout — skidding or slipping sensations make disorientation worse and slow the recovery.'),
  P('A nose-low recovery risks excess Gs and uncoordinated flight; a nose-high recovery risks an uncoordinated stall and a possible spin.'),

  S('Common Errors — AI.XI.E.K5'),
  P('Not recognizing the UA · recovering by feel instead of instrument indication (consequences can be severe) · inappropriate control application, which can aggravate or induce a UA · missing the cue for passing through level flight.'),

  S('RM: Hazards'),
  H('Inadvertent Flight into IMC — AI.XI.E.K3'),
  P('A pilot untrained in instrument flying, or with eroded skills, statistically loses control after about 10 minutes once forced to rely solely on instruments.'),
  B('Anytime you can\'t maintain control by reference to the natural horizon, that\'s IMC — recognize it and treat it as a genuine emergency.'),
  H('RM: Maintain Control — AI.XI.E.R7'),
  P('Trust the instruments — they\'re the only safe way to fly now. Priority one is wings level; an uncontrolled turn compounds control difficulty and disorientation.'),
  P('Trim for hands-off cruise, small changes (no more than a bar-width), use any automation on board, hold cruise speed until it\'s time to slow for landing. See XI.A-D for the full technique.', 3),
  A('Get help, find VMC'),
  P('Obtain assistance from ATC, Guard, or FSS, and check weather charts for the nearest expected VMC.'),
  P('The best option may be to bug your heading, engage the autopilot if available, and fly a 180° back to the last known VMC, terrain and airspace permitting.', 3),

  H('Collision Hazards — AI.XI.E.R4'),
  A('Clearing procedures'),
  P('As able: gentle banks to scan above/below the wings and other blind spots, clear the direction before any turn, pre-maneuver clearing turns above/below/front/behind, and communicate intentions and location in practice areas.'),
  A('Scanning'),
  P('As able: short, regularly spaced eye movements into central vision, no more than 10° per movement, each area held at least one second.'),
  P('Operation Lights On — a voluntary FAA safety program: landing lights on during takeoff and below 10,000\', day or night.', 3),
  A('Right-of-way — FAR 91.113'),
  P('An aircraft in distress has right-of-way over all other traffic.'),
  P('Converging: same category, right aircraft wins; different category, less maneuverable wins — balloons, gliders, airships over airplanes, a towing/refueling aircraft over engine-driven.', 3),
  P('Head-on: each pilot alters course right. Overtaking: the overtaken aircraft wins, and passes on the right.', 3),
  P('Landing: aircraft on final or landing win over those in flight or on the surface; between two, the lower one wins — don\'t abuse either rule.', 3),
  A('Terrain'),
  P('Study terminal and IFR/VFR chart altitudes and use Maximum Elevation Figures; be extra vigilant at night when terrain may be invisible until too late.'),
  P('Minimum safe altitudes (FAR 91.119): anywhere, high enough for an emergency landing without undue hazard; congested areas, 1,000\' above the highest obstacle within 2,000\'; otherwise 500\' above the surface, or from any person/vessel/vehicle/structure over open water or sparse areas.', 3),
  A('Obstacles & wire strike — AIM 7-6-4'),
  P('Know the obstacles near any airport you\'ll use — charts, terminal procedures, NOTAMs.'),
  P('Antenna towers can reach over 1,000–2,000\' AGL, with guy wires extending up to 1,500\' horizontally.', 3),
  B('Overhead transmission wires may not be lit and often span the very departures and landmarks pilots follow — lakes, highways, railroad tracks.'),

  H('Distractions, SA & Task Prioritization — AI.XI.E.R5'),
  P('Distractions are dangerous — remove them from view, or if a person, explain and ask them to stop; focus on performance especially without visual references, and if distracted, fix it.'),
  P('If SA is lost, admit it and fix it, starting from preflight planning — know what\'s coming next and stay ahead of the airplane.', 3),
  P('An upset from lost SA: Push, Roll, Thrust, Stabilize. Lack of visual references is disorienting — trust the instruments, use automation, ask for help, return to VMC.', 3),
  A('Task prioritization'),
  P('Divide attention between the aircraft, scanning, and communicating; know what needs to happen and when, using SOPs and checklists.'),
  P('Attack the closest alligator — handle the most pressing problem and go from there. Safety comes first: Aviate, Navigate, Communicate.', 3),

  S('Conclusion'),
  P('Review: environmental, mechanical, human causes · nose-high vs nose-low instrument picture · recovery basics & why the two procedures differ · Power-Pitch-Bank (nose-high) and Power-Bank-Pitch (nose-low) · coordination through recovery · common errors · inadvertent IMC and collision/terrain/SA hazards.'),
  P('Every recovery starts the same way: stop trusting your inner ear and start trusting the needles.'),
]};

/* ============================================================
   II.D — Principles of Flight (Additional Information)
   Spine: Ground Effect -> Climbs -> Descents -> Turns -> Revisiting Stalls (supplemental deep-dive, no ACS codes in source)
   ============================================================ */
window.CFI_SCRIPTS['ii-d-principles-of-flight-addt-l-info-'] = { nodes: [
  S('Introduction'),
  H('Attention'),
  P('Every force we just learned about keeps acting throughout the flight — know exactly how lift, weight, thrust, & drag shift as we climb, descend, or turn.'),
  H('Overview'),
  P('Ground effect on takeoff & landing'),
  P('Force changes entering a climb & a descent'),
  P('Turns — rate, radius, slips & skids'),
  P('Revisiting stalls — three ways to exceed critical AOA'),
  H('What'),
  P('How the same four forces behave differently the instant the flight path changes.'),
  H('Why'),
  P('A pilot who only knows steady, level-flight forces gets caught off guard the moment it climbs, turns, or slows — this fills in what changes.'),

  S('How:'),

  H('Ground Effect'),
  P('Within about one wingspan of the ground, restricted vertical airflow reduces vortex formation & downwash — induced drag drops, lift increases at the same AOA.'),
  A('Takeoff'),
  B('With less induced drag, the airplane needs less thrust to fly — it can become airborne below the speed sustaining flight out of ground effect.'),
  P('Climb out before reaching that speed & the airplane can settle back toward the runway as it leaves ground effect & drag returns.', 3),
  A('Landing'),
  P('The same drag reduction makes the airplane float through the flare — reduce power as it settles into ground effect, or the float (& landing distance) grows.'),

  H('Climbs'),
  P('In a stabilized climb, AOA & lift settle back to essentially their level-flight values at the same airspeed — only the flight path changed.'),
  A('Entering the Climb'),
  P('Raising the nose momentarily increases AOA & lift above weight — that excess starts the climb.'),
  A('Airspeed Loss Without a Power Change'),
  P('Weight now adds a rearward-acting component to drag, so thrust falls short — speed bleeds off until a new balance.'),
  P('How much airspeed is retained (& how well the airplane climbs) comes down to reserve power — extra thrust beyond what level flight requires.', 3),

  H('Descents'),
  P('Forward pressure reduces AOA & lift only while the flight path changes — once stabilized, both return to essentially level-flight values.'),
  A('Airspeed Gain Without a Power Change'),
  P('Weight now has a forward-acting component along the flight path instead of rearward — thrust exceeds drag & airspeed increases unless power is reduced.'),
  P('The steeper the descent, the larger that forward component of weight — & the more power must come out to hold airspeed.', 3),

  H('Turns'),
  A('Why the Airplane Turns'),
  P('Banking tilts lift so part of it acts inward (the horizontal component — the actual turning force) while the rest still acts upward against weight.'),
  A('Holding Altitude'),
  P('The vertical component of lift shrinks as bank increases, so AOA must increase — raising induced drag & bleeding airspeed, so power must rise with bank angle.'),
  A('Rate of Turn'),
  P('Set by the horizontal component of lift — at a given airspeed, rate of turn is controlled purely by bank angle.'),
  A('Turning Radius'),
  P('Radius grows with airspeed, & centrifugal force grows with radius — to hold the same rate of turn as speed increases, bank angle must increase too.'),
  A('Slipping Turns'),
  P('Rate of turn is too slow for the bank — horizontal lift exceeds centrifugal force & the airplane yaws outside. Correct by decreasing bank or adjusting rudder to center the ball.'),
  A('Skidding Turns'),
  P('Rate of turn is too fast for the bank — centrifugal force exceeds horizontal lift & the airplane yaws inside. Correct by reducing rate or increasing bank.'),

  S('Revisiting Stalls'),
  H('The Constant: Critical AOA'),
  B('Every stall has the same direct cause — exceeding critical AOA. Stalling SPEED isn\'t fixed — it shifts with weight, load factor, & density altitude — but stalling AOA never changes for a given airfoil (typically 16°–20°).'),
  H('Three Ways to Exceed It'),
  A('Low-Speed Flying'),
  P('As airspeed drops, AOA must rise to hold lift. At critical AOA, lift can\'t increase further — reduce airspeed even slightly more & the wing stalls.'),
  P('Classic setup: slow, high-AOA turn from base to final — exactly where an inadvertent stall is most dangerous, close to the ground.', 3),
  A('High-Speed Flying'),
  B('Low speed isn\'t required — an abrupt high-speed pull (200 knots in a dive) can snap AOA from very low to very high before the flight path responds, exceeding critical AOA well above published stall speed.'),
  A('Turning Flight'),
  P('Stall speed is higher in a turn than straight-and-level because centrifugal force adds to weight, & the wing must produce extra lift.'),
  P('That extra lift comes from back pressure, increasing AOA along with bank angle — push AOA to critical at any point in the turn & the airplane stalls, regardless of airspeed.', 3),

  S('Conclusion'),
  P('Review: ground effect · climb & descent force changes · turn rate, radius, slips & skids · the three ways to exceed critical AOA.'),
  P('The single thread: AOA is what actually changes, not lift itself — the pilot\'s real job in every phase is managing AOA.'),
]};

/* ============================================================
   II.E — Flight Controls & Operation of Systems
   Spine: Primary/Secondary Controls -> Trim -> Flaps -> Engine -> Propeller -> Fuel -> Electrical -> Brakes -> Pitot-Static -> Vacuum/Gyro -> Environmental -> Ice Protection
   (876-node source condensed via headings-first pass; assigned system order followed as given)
   ============================================================ */
window.CFI_SCRIPTS['ii-e-flight-controls-systems'] = { nodes: [
  S('Introduction'),
  H('Attention'),
  P('An airplane is a stack of interdependent systems — learn each one well enough to catch the moment it stops working right.'),
  H('Overview'),
  P('Primary controls (ailerons, elevator, rudder) & secondary controls (flaps, spoilers, trim)'),
  P('Powerplant — four-stroke cycle, ignition, induction, oil, cooling, exhaust'),
  P('Propeller — fixed pitch vs constant speed'),
  P('Fuel, electrical, avionics & autopilot'),
  P('Landing gear, hydraulics & brakes'),
  P('Pitot-static & gyroscopic flight instruments'),
  P('Environmental systems, ice protection & oxygen systems'),
  P('RM — recognizing & managing system failures (MATL)'),
  H('What'),
  P('How the airplane\'s controls & systems work individually, & what failure looks like.'),
  H('Why'),
  P('You can\'t teach a system you don\'t understand, or manage a failure in one you\'ve never studied healthy.'),

  S('How:'),

  A('Terms — Chord Line & Camber'),
  P('Chord line: imaginary straight line, leading edge to trailing edge. Camber: curve of the upper & lower surfaces — both explain how every primary control changes lift.'),

  H('Primary Flight Controls — AI.II.E.K1a'),
  P('Ailerons: roll (longitudinal axis). Elevator: pitch (lateral axis). Rudder: yaw (vertical axis) — safe flight control, operated by cables, bell cranks, pulleys, &/or push-pull tubes.'),
  A('Ailerons'),
  P('Outboard trailing edge of each wing, moving opposite each other — up-aileron decreases camber/lift, lowering the wing; down-aileron increases it, raising the wing.'),
  P('Right turn: right aileron up, left aileron down. Left turn: the reverse — the wings\' lift difference rolls the airplane.', 3),
  B('Adverse yaw: the down-aileron wing makes more lift AND more induced drag, yawing the nose toward the raised wing — rudder corrects it, most needed at low speed/high AOA/large deflections.'),
  P('4 designs fight adverse yaw: differential ailerons (up-travel exceeds down-travel), Frise-type (raised aileron\'s leading edge juts into the airflow, slotting the lowered one), aileron-rudder interconnects, & flaperons (drooping together as flaps).', 3),
  P('Interconnect example: rolling left, the cable & springs pull the left rudder pedal forward just enough to prevent adverse yaw from swinging the nose right.', 3),
  A('Elevator'),
  P('Pulling back raises the trailing edge, increasing downward tail force & pitching the nose up; pushing forward reverses it — movement strength depends on the CG-to-tail arm.'),
  P('T-tails: clear of prop wash (consistent control), but need more elevator at slow speed, more prone to deep stalls. Stabilator: all-moving tail with an anti-servo tab, preventing overcontrol.'),
  P('T-tails are also built stiffer & heavier than a conventional tail — the longer moment arm creates higher loads, risking flutter if it isn\'t.', 3),
  P('Safety systems: control stops limit elevator travel, a down-spring biases the nose down against an aft-CG stall, & stick pushers on transport jets force it down before a computer-detected stall.', 3),
  A('Rudder'),
  P('Deflects into the airflow, creating a horizontal force yawing the nose that way — maintains coordination against adverse yaw & left-turning tendencies.'),
  P('V-tails: ruddervators, mixed by linkage, doing the job of both elevator & rudder — more complex, more prone to Dutch roll, minimal drag saved.'),

  H('Secondary Flight Controls — AI.II.E.K1b'),
  A('Flaps'),
  P('Trailing-edge devices increasing lift & drag for a given AOA — lower takeoff/landing speed, shorter runway, or a steeper approach.'),
  P('Functions: takeoff (airborne at lower speed, shorter roll, better climb) · approach (added drag allows a steeper approach) · landing (lower speed, shorter distance).', 3),
  P('Plain (simplest) · Split (more drag, little more lift) · Slotted (most common — ducted air delays flow separation, big lift gain) · Fowler (slides aft then down, increases wing area — most lift, least initial drag).', 3),
  P('Flap control is mechanical, electrical, or hydraulic — know the flap speed limits before extending them.', 3),
  A('Spoilers'),
  P('Spoil lift & drag on purpose — steepen descents without gaining airspeed, dump lift on landing (plants wheels, transfers weight to brakes), & (one wing at a time) assist roll, adverse-yaw-free.'),
  A('Trim Systems'),
  P('A small tab on a primary control\'s trailing edge, relieving the pilot from constant pressure — moving it into the airstream deflects the main surface the opposite way.'),
  P('Balance tabs: move automatically opposite the control input. Servo tabs (large aircraft): move the whole surface via airflow. Antiservo tabs: add resistance on a stabilator. Ground-adjustable tabs: bent by hand between flights.', 3),
  P('Some aircraft trim the entire horizontal stabilizer instead of a tab, jackscrew-driven — crank-operated on light aircraft, motor-driven on large ones.', 3),
  B('Rule: set power, pitch, & configuration first — THEN trim to relieve pressure. Re-trim every time any of the three changes.'),

  H('Powerplant — Four-Stroke Reciprocating Engine — AI.II.E.K1c'),
  P('Converts chemical energy (fuel) to mechanical energy in the cylinders — pistons drive the crankshaft, which drives the propeller.'),
  A('Engine Components'),
  P('Cylinders hold intake/exhaust valves, spark plugs, & pistons: valves pass mixture in/exhaust out, plugs ignite it, pistons drive the crankshaft.'),
  P('The crankcase houses the crankshaft & connecting rods; the accessory housing carries the magnetos that feed the spark plugs.', 3),
  A('The Four-Stroke Cycle'),
  P('Intake (piston down, mixture enters) · Compression (piston up, mixture compressed, then ignited) · Power (ignited mixture drives the piston down, turning the crankshaft) · Exhaust (piston up, spent gas pushed out).'),
  P('Horizontally opposed cylinders are the most common GA arrangement — compact, air-cooled, high power-to-weight.', 3),
  A('Spark Ignition vs. Compression Ignition'),
  P('Spark ignition: the long-standing GA standard, a plug fires the mixture. Compression ignition (diesel/jet-fuel, e.g. the DA42): compresses air hot enough to auto-ignite injected fuel — simpler, cheaper, gaining ground; core mechanics match.'),
  A('Ignition System'),
  P('Two engine-driven magnetos per engine, each independent of the aircraft electrical system, fire the plugs. Impulse coupling: retards/snaps one magneto for a hot start spark at low RPM.'),
  P('Ignition switch: OFF · R (right mag only) · L (left mag only) · BOTH · START. Dual ignition (2 plugs/cylinder) improves combustion & means one failed magneto or plug still leaves the engine running, just weaker.', 3),
  A('Induction — Carburetor vs. Fuel Injection'),
  P('Float carburetor: venturi low pressure draws fuel from the float chamber into the airstream — simple but prone to carb ice (most likely below 70°F, humidity above 80%; fixed-pitch: falling RPM, constant-speed: falling MP first). Carb heat prevents/cures it, costing up to 15% power.'),
  P('Float-type is by far the most common carburetor; pressure-type (rare) delivers fuel under pump pressure instead of venturi suction.', 3),
  P('Fuel injection sends fuel straight to (or just ahead of) each cylinder — better cold starts, less icing, but harder hot starts & ground vapor-lock risk.', 3),
  P('Components: engine-driven pump, an auxiliary start/emergency-backup pump, a mixture-metering fuel-air control unit, a distribution manifold, & discharge nozzles at each cylinder.', 3),
  A('Oil System'),
  P('Lubricates, cools, seals the piston/cylinder wall, carries away contaminants. Wet-sump (oil in the engine): standard GA; dry-sump (external tank): larger engines needing more volume.'),
  P('Oil pressure gauge: direct, immediate read on the system. High oil temp: plugged line, low quantity, blocked cooler, or bad gauge. Low oil temp: wrong viscosity for cold weather.', 3),
  A('Cooling & Exhaust'),
  P('Air-cooled is standard for small aircraft — effective only with airflow, so a high-speed low-power descent can shock-cool the engine. CHT: direct/immediate temperature indicator; oil temp lags.'),
  P('Liquid cooling (water, ethylene glycol, or a mix) pumped around the hot components avoids shock-cooling & targets specific areas — at the cost of weight & complexity.', 3),
  P('Controlling a rising temperature: increase airspeed, enrich the mixture, reduce power, open cowl flaps.', 3),
  P('Exhaust also feeds cabin heat (shroud around the muffler) & the EGT probe, which reads mixture setting from exhaust gas temperature.', 3),
  B('FADEC (where installed) runs ignition & fuel electronically with two redundant channels, simplifying the flight deck to a single throttle — losing it entirely means losing engine power, so know the backup.'),

  H('Propeller — AI.II.E.K1c'),
  P('A rotating airfoil, twisted hub (highest pitch) to tip (lowest pitch) so every station produces lift efficiently — untwisted, it\'d stall at the tip & go negative-AOA at the hub.'),
  A('Installation'),
  P('Direct-drive props turn at crankshaft RPM. Geared installations run the prop at a different RPM — the DA42, e.g., gears 1.69:1 engine-to-prop.'),
  A('Fixed-Pitch Propellers'),
  P('Blade angle is manufacturer-set & fixed — best efficiency at only one airspeed/RPM combo. Climb prop: lower pitch, more RPM/HP for takeoff/climb. Cruise prop: higher pitch, better cruise, worse climb.'),
  P('Tachometer is the only control reference — RPM follows throttle directly.', 3),
  A('Constant-Speed Propellers'),
  P('A governor changes blade angle automatically to hold the pilot-selected RPM — more efficient across every flight phase. Throttle sets manifold pressure (power); prop control sets RPM via the governor.'),
  B('Adjusting power: decrease MP before RPM (top of the green first) · increase RPM before MP. Reducing RPM before pulling MP back can overboost the engine.'),

  H('Fuel System — AI.II.E.K1e'),
  P('Delivers clean, uninterrupted fuel under all flight conditions: gravity-feed (high-wing aircraft) or fuel-pump systems — the latter pairing an engine-driven primary pump with an electric start/backup auxiliary.'),
  A('Tanks, Selectors & Contamination'),
  P('Tanks are vented (atmospheric pressure), include an overflow drain, & drain through a water/sediment strainer — drain before every flight; water\'s the #1 contaminant, shown by cloudy fuel or a separation layer.'),
  P('Fuel selector settings typically include Left, Right, Both, Off — "Both" isn\'t available on every aircraft (some require switching L/R).', 3),
  A('Fuel Primer'),
  P('Assists cold starts, drawing fuel from the tank & vaporizing it directly into the cylinders ahead of engine start.'),
  A('Gauges'),
  B('Certification only requires the fuel quantity gauge to be accurate at EMPTY — always cross-check the tank visually, don\'t trust the gauge alone.'),
  P('A fuel pressure gauge comes with any installed fuel pump, reading pressure directly in the lines.', 3),

  H('Landing Gear, Hydraulics & Brakes — AI.II.E.K1d/K1e'),
  P('The airplane\'s principal support — wheels, floats, or skis by surface. Fixed gear trades speed for simplicity & low maintenance; retractable gear streamlines the airplane & cuts drag.'),
  P('Tricycle gear (nosewheel): harder braking without nosing over, better forward visibility, ground-loop resistance (CG ahead of the mains). Tailwheel gear: more prop clearance & rough-field capability, but harder directional control, blocked visibility.'),
  A('Hydraulics'),
  P('Reservoir, pump, filter, selector/relief valves, an actuator or servo — the selector valve sets fluid direction, the relief valve vents excess pressure.'),
  P('Servos can be single- or double-acting, with fluid applied to one or both sides of the piston.', 3),
  A('Brakes'),
  P('Mounted on the main wheels, applied by hand control or (most common) toe pedals — independent pedals allow differential braking, supplementing ground steering.'),

  H('Electrical System — AI.II.E.K1f'),
  P('Most GA aircraft run 14- or 28-volt DC: alternator/generator, battery, master/battery switch, alternator/generator switch, bus bar, fuses/breakers, voltage regulator, & an ammeter or loadmeter.'),
  A('Generation & Protection'),
  P('Alternators beat generators — full output even at low RPM, more constant across the range. The voltage regulator keeps output above battery voltage, charging it. Circuit breakers reset in flight; fuses can\'t.'),
  P('The bus bar ties alternator/generator/battery to every electrical component, distributing power; the battery mainly supplies engine start & limited backup power if the alternator fails.', 3),
  A('Reading the Ammeter'),
  P('Zero-center gauge: positive deflection = battery charging, negative = discharging, full-scale either direction = a malfunction. A loadmeter instead shows percent load on the alternator/generator directly.'),
  P('Not every aircraft has an ammeter — some carry only a warning light for a malfunction instead.', 3),

  H('Avionics & Autopilot — AI.II.E.K1g'),
  A('Avionics'),
  P('Glass panels (G1000, Avidyne, & similar): instrument displays, GPS, autopilot, & radios in one system, alongside any remaining traditional instruments — know your avionics & operating manual.'),
  B('Manage the automation instead of getting absorbed by it — glass-panel functionality is nearly unlimited, & it\'ll happily eat your scan if you let it.'),
  A('Autopilot'),
  P('Holds level flight or a set course, pilot-directed or radio-nav-coupled — cuts pilot workload, raises safety when used correctly.'),
  P('Single-axis autopilots move only the ailerons (roll). Three-axis systems add elevator/rudder servos for pitch & yaw, often with vertical-speed or airspeed-hold modes, coupling to GPS/inertial nav via a flight director.', 3),
  B('Every autopilot needs a disconnect — know where it is & use it the instant the automation does something you didn\'t command.'),

  H('Pitot-Static Flight Instruments — AI.II.E.K1h'),
  P('Airspeed indicator, altimeter, & VSI use the same two pressures: static (still air, flush port) & pitot (impact pressure, facing the relative wind). Pitot feeds only the ASI; static feeds all three.'),
  A('Altimeter'),
  P('Aneroid wafers compress/expand with static pressure; the Kollsman window sets reference pressure — 1" Hg equals 1,000 feet, & 29.92" Hg is standard pressure altitude.'),
  B('From hot to cold, or high to low, look out below: true altitude reads LOWER than indicated either way, closing the margin you think you have.'),
  A('Vertical Speed Indicator'),
  P('A diaphragm reacts to static pressure immediately while the case lags — the difference shows climb/descent rate. Trend shows instantly; stabilized rate takes about 6–9 seconds, so treat the first reading as a trend, not a number.'),
  A('Airspeed Indicator & Electronic Displays'),
  P('A differential-pressure diaphragm compares pitot to static pressure directly. Glass-panel Air Data Computers process the same inputs digitally — no diaphragms or gearing, same info.'),

  H('Vacuum & Gyroscopic Instruments — AI.II.E.K1h'),
  P('Gyros use rigidity (resists displacement — attitude & heading indicators) & precession (force felt 90° later in the rotation — turn instruments) to work.'),
  A('Power Sources'),
  P('Electric motors, or a vacuum/pressure pump pulling air across the gyro wheel — dry pumps (no airstream oil) are standard at altitude; a gauge confirms the system\'s within range.'),
  P('Twin-engine aircraft often run 2 dry pumps feeding a common manifold through a check valve — if one engine/pump fails, the valve isolates it & the good side keeps gyros running.', 3),
  A('Attitude & Heading Indicators'),
  P('Attitude indicator: double-gimbal keeps the horizon bar level through pitch & roll — minor errors after rapid acceleration or a steep 180° turn, fixed by the erection mechanism.'),
  P('Heading indicator: rigidity holds a heading set from the compass, but precession plus earth\'s 15°/hour rotation drift it — reset against the compass every 15 minutes.', 3),
  A('Turn Instruments'),
  P('Turn-and-slip shows rate/direction of turn only; the turn coordinator (canted gyro, more common in GA) also senses roll rate, setting standard-rate turns (3°/second) via the little airplane\'s wing against the index.'),
  P('Both are backup bank-attitude sources if the attitude indicator fails. Glass panels replace this with AHRS: solid-state, no tumbling, magnetometer heading.', 3),

  H('Environmental Systems — AI.II.E.K1i'),
  A('Heating'),
  P('Exhaust-shroud heat: simplest, most common on trainers — inspect for cracks, since that air goes straight to the cabin. Fuel-fired heaters (portable/small-aircraft): burn their own fuel, fan heat in, independent of engine exhaust.'),
  P('Combustion heaters (larger aircraft) add an overheat switch & are pressure-designed so leaks vent outward, not into the cabin. Bleed-air heat serves turbine aircraft.', 3),
  P('Bleed-air safety: temperature sensors cap cabin heat, check valves protect bleed air during start & full power, & engine sensors cut the system if the engine quits.', 3),
  A('Pressurization'),
  P('Two reasons to fly high: better fuel efficiency for a given airspeed, & topping bad weather/turbulence — pressurization makes that survivable.'),
  P('Seals the cabin to hold a higher pressure than outside air (differential pressure) — compressed via engine bleed air, a supercharger, or (piston aircraft) the turbocharger through a sonic venturi.'),
  P('Outflow valve balances constant inflow against the target differential; the safety valve stacks pressure relief, vacuum relief, & emergency dump in one unit. Cabin diff-pressure gauge & altimeter cross-check it.', 3),

  H('Ice Protection — Deice & Anti-Ice — AI.II.E.K1j'),
  P('Anti-ice PREVENTS ice; deice REMOVES it. Both protect the wing/tail leading edges, pitot-static ports, fuel vents, stall warning devices, windscreen, & propeller.'),
  A('Airfoil Protection'),
  P('Pneumatic deice boots inflate to crack ice off the leading edge, cycled singly or automatically, powered by an engine-driven pump or bleed air, monitored on a suction/pneumatic gauge.'),
  P('Thermal anti-ice bleeds hot air to the leading edge, activated before entering icing conditions. Weeping-wing systems ooze antifreeze through the leading edge — capable of both deice & anti-ice.', 3),
  A('Windscreen & Propeller'),
  P('Windscreen: alcohol flow (used early, before ice builds) or embedded electric heating elements. Propeller: alcohol slung by centrifugal force through grooved boots, or built-in electric heating elements.'),

  H('Oxygen Systems — AI.II.E.K1l'),
  A('Fixed vs. Portable'),
  P('Most high-altitude aircraft carry a fixed installation; otherwise portable equipment — container, regulator, mask outlet, pressure gauge — must stay accessible in flight.'),
  P('Bottles run 1,800–2,200 psi (pressure drops with ambient temperature) & should be marked with their pressure tolerance before filling.', 3),
  A('Masks & Cannulas'),
  P('Masks need a good seal & a mic, & can deliver pressure-demand oxygen; cannulas are more comfortable but less efficient.'),
  B('Regulations require masks, not cannulas, on any O2 system certified above 18,000 feet.'),
  A('Types of Oxygen Systems'),
  P('Continuous flow (usually for passengers) mixes oxygen with ambient air & stores extra in a reservoir bag filling while exhaling.'),
  P('Diluter-demand (to 40,000 ft): oxygen only on inhalation, straight 100% or diluted with cabin air. Pressure-demand: pressurizes the lungs above 34,000 ft. Electric pulse-demand: senses each inhalation, cuts oxygen use 50–85% vs continuous flow, barometer-raising the dose with altitude.', 3),
  A('Aviator\'s Breathing Oxygen & Storage'),
  B('Use aviation oxygen only — minimum 99.5% purity, no more than 0.005 mg of water vapor per liter. Other grades carry moisture that can freeze a regulator at altitude.'),
  P('Keep portable equipment accessible in flight, respect the fire danger oxygen creates, & inspect/test all oxygen equipment on a regular schedule.'),

  S('RM: System Failures & Automation — AI.II.E.K2/R1'),
  H('RM: Managing & Monitoring Automation — AI.II.E.R3'),
  P('Managing: automation is only as good as the inputs it\'s given — understand the system\'s capabilities & set it up correctly beforehand.'),
  P('Monitoring: follow what the automation is doing; know expected operation, ranges, limitations, & warning annunciations, & reference the POH or act the moment something reads out of range.'),
  H('Recognizing Malfunctions or Failures'),
  P('Specific to the aircraft & its systems — EFD warnings, caution/warning lights, & gauge indications all say the same thing in different languages: something changed.'),
  H('Managing an Airborne Failure — MATL — AI.II.E.R2'),
  A('M — Maintain aircraft control'),
  P('Fly the airplane first — get to a safe flight state (straight-and-level), trim it, engage automation if it helps, & hold control through the malfunction.'),
  A('A — Analyze the situation'),
  P('Gather every indication — lights, sounds, smoke, leaks, fire, smells — & use all of it to find the actual issue.'),
  A('T — Take proper action'),
  P('Apply memory items first, then run the appropriate checklist from the POH.'),
  A('L — Land, as conditions require/permit'),
  P('Decide the landing area based on the emergency — divert, off-field, or ditching — running it alongside the checklist(s), never instead.'),
  H('Managing a Failure on the Ground — AI.II.E.R2'),
  P('Remain on the ground. Analyze the situation the same way, run the appropriate checklist, & decide: continue the flight, return to park, or evacuate.'),
  H('RM: Flight Instruction in Unfamiliar Aircraft, Systems & Avionics — AI.II.E.R4'),
  B('Just because it\'s legal doesn\'t mean it\'s safe — be proficient in any aircraft you fly, let alone instruct in, for your safety & the learner\'s time, money, & education.'),

  S('Conclusion'),
  P('Review: primary & secondary controls · trim · engine 4-stroke/ignition/induction/oil/cooling · propeller fixed vs constant-speed · fuel · electrical · avionics & autopilot · gear/brakes · pitot-static · vacuum/gyro · environmental · ice protection · oxygen systems · MATL failure management.'),
  P('The instructor\'s real job: know each system well enough to recognize immediately when it\'s NOT behaving normally, & know what to do about it.'),
]};

/* ============================================================
   X.F — Cross-Controlled Stalls
   Spine: Disconnect·Pitch·Roll·Thrust·Stabilize·Configure recovery, PARE spin contingency
   ============================================================ */
window.CFI_SCRIPTS['x-f-cross-controlled-stalls'] = { nodes: [
  S('Introduction'),
  H('Attention'),
  P('An overshooting base-to-final turn can flip an airplane inverted before you register it — stay coordinated in every turn, especially close to the ground.'),
  H('Overview'),
  P('The overshoot scenario that sets up a cross-controlled stall'),
  P('Why opposite aileron and rudder stall a wing without warning'),
  P('Setup, entry, and the six-step recovery'),
  P('The spin contingency (PARE)'),
  P('Common errors (AFH 5-21)'),
  P('RM: environmental, collision, and task-management hazards'),
  H('What'),
  P('A stall with aileron one way and rudder the other — most often overshooting base to final.'),
  H('Why'),
  B('The classic base-to-final accident: low altitude, a worsening instinct, and almost no time to recover.'),

  S('How:'),

  H('The Overshoot — AI.X.F.K1'),
  A('30° Bank Turn to Final, Overshooting the Centerline'),
  P('Wind pushes past the extended centerline turning base to final.'),
  A('The instinctive fix'),
  P('More rudder tightens the turn without steepening bank — opposite (right) aileron and back pressure hold the nose and bank in place.'),
  A('What crossed controls actually does'),
  P('Opposite aileron raises AOA on the inside (low) wing, lowers it outside; back pressure raises both — the inside wing, already highest, stalls first and can roll the airplane inverted.', 3),
  A('The wrong reaction'),
  B('More aileron to roll level steepens AOA on the stalled wing; pulling up deepens it. Stall plus yaw is a spin.'),
  P('Stay coordinated low to the ground. Overshooting? Go around, don\'t save the turn.'),

  H('RM: Limitations — AI.X.F.R4'),
  P('POH Chapter 2 for aircraft limitations on cross-controlled stalls.'),

  H('Recognizing the Setup — AI.X.F.K2/K3'),
  P('Any time aileron and rudder oppose — most likely on an overshooting base-to-final turn. Stay alert for it.'),

  H('Setup & Entry — AI.X.F.K4'),
  P('Pre-maneuver checklist, clear the area, entry altitude no lower than 3,000\' AGL (ACS).'),
  P('Close the throttle, gear down if retractable, no flaps, hold altitude as speed decays, trim for glide.'),
  H('Performing It'),
  P('Roll into a medium bank simulating the overshoot: 30° of excessive rudder toward the turn, opposite aileron, and back pressure — increase all three until the stall breaks.'),
  P('Can break with little warning: the horn may not sound, and buffet may arrive late or not at all, from the sideslip.', 3),

  H('RM: Recovery — Disconnect · Pitch · Roll · Thrust · Stabilize · Configure — AI.X.F.K5/R1'),
  B('Recover before an abnormal attitude develops.'),
  A('Pitch'),
  P('Nose down to reduce AOA and clear the stall warning.'),
  A('Roll'),
  P('Release the excessive rudder and level the wings.'),
  A('Thrust · Stabilize · Configure'),
  P('Power as needed, return to the desired flight path, and reconfigure. Disconnect rarely applies here.'),

  H('If It Spins — PARE'),
  P('Power idle · Ailerons neutral · Rudder opposite the spin · Elevator briskly forward, then relax rudder and ease back to level.'),

  S('Common Errors — AFH 5-21'),
  P('Inadequate clearing; leaning on airspeed/slip-skid over other cues.'),
  P('Missing the impending stall, or cutting the recovery short.'),
  P('Losing bank angle or coordination through stall and recovery.'),
  P('Forgetting to disconnect autopilot/wing leveler before reducing AOA.'),
  P('Recovering out of order — wings or power before AOA reduces.'),
  P('Releasing forward pressure too soon, or holding too much.'),
  P('Pulling too fast on entry or recovery (accelerated/secondary stall).'),
  P('Excess airspeed on recovery; losing SA or an ATC clearance.'),

  S('RM: Hazards'),
  H('Environmental Elements — AI.X.F.R2'),
  A('Turbulence'),
  P('Raises effective stall speed — gusts can exceed critical AOA. Higher approach speed in turbulence or strong crosswinds.'),
  A('Microbursts'),
  P('Downdrafts to 6,000 fpm, shear beyond 100 kt — avoid thunderstorms, heavy rain; don\'t chase the descent with pitch.'),
  A('High density altitude'),
  P('Thinner air, less power, thrust, lift — true stall speed runs higher than the gauge shows.'),
  H('Collision & Terrain — AI.X.F.R3'),
  P('Clear before every maneuver — short scanning sweeps, a second each — lights below 10,000\', never lean on FAR 91.113.'),
  P('Know 91.119 minimums; expect towers, guy wires, unlit wires near lakes, highways, rail lines.', 3),
  H('Distractions, SA & Task Management — AI.X.F.R5'),
  B('Aviate, Navigate, Communicate — fly first; if SA slips, admit and fix it.'),

  S('Conclusion'),
  P('Review: overshoot setup · crossed-control aerodynamics · setup/entry/recovery · PARE if it spins · common errors · environmental, collision, task-management hazards.'),
  P('One habit prevents this: overshooting final means go around, not fixing it with rudder.'),
]};

