/* ============================================================
   X.I — Spin Awareness & Spins
   Spine: 4 spin phases (Entry/Incipient/Developed/Recovery), PARE recovery
   ============================================================ */
window.CFI_SCRIPTS['x-i-spins'] = { nodes: [
  S('Introduction'),
  H('Attention'),
  P('Spin training removes the mystery — pilots learn to recognize, avoid, and if needed recover from one on purpose, at altitude, long before it\'s required.'),
  H('Overview'),
  P('Spin aerodynamics — stall + yaw = autorotation'),
  P('The 4 phases: Entry, Incipient, Developed, Recovery'),
  P('Factors that make a stall/spin more or less likely'),
  P('Recognizing spin situations & stall warning limitations'),
  P('Intentional spins — what has to be true first'),
  P('Preflight, pre-maneuver, entry, and PARE recovery'),
  P('Common errors (AFH 5-21)'),
  P('RM: environmental, collision, and task-management hazards'),
  H('What'),
  P('An aggravated stall resulting in autorotation — one wing more stalled than the other, rolling, yawing, and pitching around the vertical axis.'),
  H('Why'),
  B('Trained to avoid the stall, recover from it before it spins, and — if both fail — recover from the spin itself.'),

  S('How:'),

  H('Spin Aerodynamics — AI.X.I.K3'),
  P('A spin needs a stall plus yaw: the inboard, lower wing is more stalled than the outboard — unequal lift/drag drives the autorotation.'),
  A('Why it autorotates'),
  P('Dropping wing: rising AOA — less lift, more drag. Rising wing: falling AOA — more lift, less drag. Lift difference rolls it, drag difference yaws it.', 3),
  A('Load factor'),
  P('Usually just above 1G — airspeed stays within about 2 kt of unaccelerated stall speed, pivoting rather than turning.'),

  H('4 Phases of a Spin'),
  A('Entry'),
  P('The elements are in place: stall plus yaw.'),
  A('Incipient'),
  P('From the start of the stall/rotation until the spin fully develops — typically 2 to 4 turns; airspeed stabilizes low, and the turn coordinator shows the spin direction.'),
  A('Developed'),
  P('Aerodynamic and inertial forces balance; rotation, airspeed, and vertical speed stabilize in a near-vertical flightpath. Some airplanes transition to a spiral dive here instead — airspeed accelerating and G-load rising, which a true spin never does.', 3),
  A('Recovery'),
  P('Rotation stops and AOA is reduced below critical — the spin is broken.'),

  H('Factors That Set Up a Stall/Spin — AI.X.I.K2'),
  P('A stall can happen at any airspeed, attitude, or power setting — it\'s about AOA, not speed.'),
  A('Airspeed & power'),
  P('Low speed needs higher AOA until exceeded; a fast pull-up can hit critical AOA above published stall speed (accelerated stall). High power, low airspeed, high AOA sharply raise left-turning tendency — anticipate right rudder.', 3),
  A('Configuration & load factor'),
  P('Flaps raise stall margin; load factor rises with steep turns, dive pull-outs, brisk inputs — stall speed rises with the square root of load factor.', 3),
  A('Bank Angles Above 45° Impose Tremendous Loads'),
  P('Every banked turn adds load factor — it climbs fast once bank passes 45°.'),
  A('Weight & CG'),
  P('Heavier or more aft-loaded airplanes stall slower but recover worse.', 3),
  A('Farther Forward CG — Greater Tendency for the Nose to Pitch Down'),
  P('Forward CG stalls a bit faster but is more controllable and recoverable — the nose wants to drop on its own.'),
  A('Ice, snow, & frost'),
  P('Raises stall speed, disrupts airflow below critical AOA, adds weight — 0.8 mm on the upper wing can cut lift 25%.', 3),
  A('Yaw'),
  B('Stall + yaw = spin. Coordination — keeping the ball centered through the whole maneuver — is the actual prevention.'),

  H('RM: Recognizing Spin Situations — AI.X.I.K7/R1'),
  P('Any time stall and yaw can occur together: an uncoordinated go-around or short-field takeoff (high pitch, high power, low airspeed), an overshooting base-to-final turn cross-controlled, or an unrecognized stall from distraction or surprise.'),
  A('Stall warning range & limitations — AI.X.I.R2'),
  P('Buffet usually comes first but isn\'t guaranteed — a cross-controlled stall can break with almost no warning. Per 23.207 the horn must be clear and distinct, sound at least 5 kt above stall speed, and give time to act — ranges vary by airplane.', 3),
  P('A sloppy stall recovery is generally a coordination failure — uncontrolled yaw.'),
  P('Practicing stall and spin recognition builds the instinct to catch it early — AI.X.I.K10.'),

  H('Intentional Spins — AI.X.I.K6'),
  B('Never intentionally spin an airplane that is not approved for spins.'),
  P('Check the Airworthiness Category, Type Certificate Data Sheet, and AFM/POH limitations — or look for a placard prohibiting spins.'),
  P('If approved, check weight & balance too (a minor shift can change recoverability — a Utility-category airplane outside Utility limits may not recover) and the manufacturer\'s recommended entry and recovery.'),

  H('Spin Procedures — AI.X.I.K1'),
  A('Preflight'),
  P('Extra emphasis on loose items that could shift weight or CG, CG limits, and slack rudder or elevator cables — any can prevent recovery.'),
  A('Pre-maneuver — AI.X.I.K8'),
  P('Pre-maneuver checklist, clear the area, entry altitude no lower than 4,000\' AGL (ACS) — AFH wants recovery complete no lower than 1,500\' AGL. Budget 1,000\' for the first turn, 500\' each after.'),

  S('The Maneuver'),
  H('Entry'),
  P('Like a power-off stall: idle power raising the nose to stall attitude; at the stall, full rudder in the spin direction, full back pressure, neutral ailerons.'),
  A('Maintaining the spin — AI.X.I.K9'),
  P('Hold full back pressure and full rudder, ailerons neutral.'),
  A('Staying oriented — AI.X.I.K11'),
  P('Pick an outside reference and cross-check the turn coordinator — it deflects toward the spin and stays reliable. Gyro indicators can tumble and mislead; ignore them.'),
  H('Incipient & Developed'),
  P('Incipient: aerodynamic and inertial forces have not balanced yet — airspeed near or below stall, turn coordinator confirming direction.'),
  P('Developed: forces balance and the spin self-sustains — or transitions into a spiral dive, recognizable by rising airspeed and G-load a real spin never shows.'),

  H('RM: Recovery — PARE — AI.X.I.K4/K12/R3'),
  B('Follow the manufacturer\'s published procedure if one exists. Recovery can take anywhere from a quarter-turn to several turns.'),
  A('P — Power idle'),
  P('Power aggravates a spin — flattens it and speeds up rotation.'),
  A('A — Ailerons neutral'),
  P('Aileron into the spin speeds rotation and steepens it; aileron against the spin can flatten it and make recovery harder or impossible.'),
  A('R — Rudder opposite the rotation'),
  P('Briskly apply and hold full opposite rudder until rotation stops.'),
  A('E — Elevator briskly forward'),
  P('Apply immediately after full rudder — do not wait for rotation to stop — and hold it to reduce AOA and break the stall. Rising airspeed means you are no longer spinning.', 3),
  A('Then: rudder neutral, elevator back to level'),
  P('Neutralize rudder as soon as rotation stops or you risk a yaw/skid or a spin the other way; ease the nose back to level, watching for a secondary stall or exceeding load limits.'),

  H('RM: Parachutes — FAR 91.307'),
  P('Carrying any person other than a crewmember, you may not intentionally exceed 60° of bank or a 30° nose-up/nose-down pitch attitude unless each occupant wears an approved parachute.'),
  P('Exceptions: certification or rating flight tests, and spins or other maneuvers required by the regulations for a certificate or rating when given by a CFI. Spin training with you aboard falls under that instructional exception.'),
  P('The exception covers required training, not joyriding — verify it applies before relying on it, and always confirm the airplane itself is approved for the maneuver first.', 3),

  S('Common Errors — AFH 5-21'),
  P('Not applying full rudder on entry, or not holding full up-elevator — can produce a spiral instead of a spin.'),
  P('Entering before the airplane is fully stalled.'),
  P('On recovery: not applying full opposite rudder briskly, not enough forward elevator, or waiting for rotation to stop first.'),
  P('Not neutralizing rudder once rotation stops, risking a secondary spin.'),
  P('Slow, overly cautious control movements during recovery.'),
  P('Too much back pressure after rotation stops (secondary stall risk), or too little (excess airspeed).'),

  S('RM: Hazards'),
  H('Environmental Elements — AI.X.I.R4'),
  A('Turbulence'),
  P('Raises stall speed — gusts can exceed critical AOA. Higher approach speed in turbulence or strong crosswinds.'),
  A('Microbursts'),
  P('Downdrafts to 6,000 fpm, shear beyond 100 kt — avoid thunderstorms, heavy rain; don\'t chase the descent with pitch.'),
  A('High density altitude'),
  P('Thinner air, less power, thrust, lift — stall speed runs higher than the gauge shows.'),
  H('Collision & Terrain — AI.X.I.R5'),
  P('Clear before every maneuver — short scanning sweeps, a second each — lights below 10,000\', never lean on FAR 91.113.'),
  P('Know 91.119 minimums; expect towers, guy wires, unlit wires near lakes, highways, rail lines.', 3),
  H('Distractions, SA & Task Management — AI.X.I.R6'),
  B('Aviate, Navigate, Communicate — fly first; if SA slips, admit and fix it.'),

  S('Conclusion'),
  P('Review: stall + yaw = autorotation · 4 phases · factors that set it up · recognizing the situation · 91.307 · preflight/pre-maneuver/entry · PARE · common errors · environmental, collision, task-management hazards.'),
  P('One sequence carries the whole lesson: Power idle, Ailerons neutral, Rudder opposite, Elevator briskly forward — applied without hesitation.'),
]};

