/* ============================================================
   XV.A — Energy Management
   Spine: PE+KE · thrust-drag balance · throttle=total energy, elevator=distribution · 3 rules
   ============================================================ */
window.CFI_SCRIPTS['xv-a-energy-management'] = { nodes: [
  S('Introduction'),
  H('Attention'),
  P('Every deviation in altitude or airspeed is an energy problem in disguise — read pitch and power as one system, not two knobs.'),
  H('Overview'),
  P('The airplane as an energy system — potential plus kinetic'),
  P('The energy balance equation — thrust vs drag'),
  P('Throttle controls total energy, elevator controls its distribution'),
  P('The 3 rules of energy control'),
  P('Energy errors — total energy vs distribution'),
  P('Unrecoverable deceleration and sink rate'),
  H('What'),
  P('Managing the airplane\'s total mechanical energy, and its split between altitude and airspeed, to hold a stable flight path.'),
  H('Why'),
  B('Loss of control, CFIT, and approach/landing accidents all trace back to an energy state the pilot didn\'t recognize in time.'),

  S('How:'),

  H('The Airplane as an Energy System'),
  P('Total mechanical energy is the sum of potential energy (altitude) and kinetic energy (airspeed).'),
  P('An airplane in flight is an "open" system — thrust adds energy, drag removes it, and energy shifts between airspeed and altitude.'),

  H('Energy Balance Equation — Thrust vs Drag'),
  P('If thrust exceeds drag (T > D), total energy increases and can go to airspeed or altitude.'),
  P('If thrust is less than drag (T < D), total energy decreases, producing a descent or a deceleration.'),
  P('If thrust equals drag (T = D), total energy is constant — any airspeed or altitude change simply trades one for the other.'),
  B('The equation always balances: any change in total energy from thrust and drag shows up as a change in altitude or airspeed, in every phase of flight.'),

  H('Pilot Control of Energy'),
  A('Throttle — the total energy controller'),
  P('Regulates energy by increasing or decreasing thrust; total energy changes are normally initiated by thrust, not drag.'),
  P('Set to match the total energy the desired flight-path/speed profile needs.'),
  A('Elevator — the energy distribution controller'),
  P('Adjusts pitch to allocate total energy between the vertical flight path and airspeed.'),
  P('With the profile established, pitch sets the split between altitude and speed.'),
  B('Throttle and elevator are energy state controls — neither controls altitude or airspeed alone; they must coordinate to hold a stable profile.'),

  H('Front & Back Side of the Power Curve'),
  A('Front side of the power curve'),
  P('High speed, low AOA, no excess power — pulling back briefly trades speed for a climb, since reduced speed means reduced drag (T minus D turns positive).'),
  P('With excess power available, the airplane can climb at constant airspeed or turn level.', 3),
  A('Back side of the power curve'),
  P('Low speed, high AOA, no excess power — pushing forward briefly trades altitude for speed, since faster also reduces drag here.'),
  P('Elevator can also directly increase drag in turns: pulling back raises AOA and load factor, burning total energy faster than throttle alone.', 3),

  H('The 3 Rules of Energy Control'),
  A('Increase total energy'),
  P('Increase throttle so thrust exceeds drag, then pitch to distribute the gain — climb while holding airspeed, or accelerate while holding altitude.'),
  A('Decrease total energy'),
  P('Reduce throttle so drag exceeds thrust, then pitch to distribute the loss — descend while holding airspeed, or decelerate while holding altitude.'),
  A('Exchange energy without changing the total'),
  P('Pitch up to trade speed for altitude, pitch down to trade altitude for speed.'),
  P('In all three cases, once the new energy state is reached, adjust pitch and throttle to hold the new profile.', 3),

  H('Energy Errors — Unintended Altitude-Airspeed Deviations'),
  A('Total Energy Errors'),
  P('Altitude and airspeed deviate in the same direction — low and slow, or high and fast.'),
  P('Corrected with the throttle, by adding or removing total energy.'),
  A('Distribution Errors'),
  P('Total energy is correct but split wrong — altitude and airspeed deviate opposite ways, high/slow or low/fast.'),
  P('Corrected with the elevator, by exchanging altitude and airspeed.'),
  A('Combined errors'),
  P('When both total energy and its distribution are off, throttle and elevator are used together.'),
  P('Example: below glidepath on final — crosscheck airspeed first, since low/slow, low/fast, and low/on-speed each need a different fix.', 3),

  H('Unintentional, Irreversible Deceleration or Sink Rate'),
  P('An unrecoverable depletion of energy — airspeed and/or altitude lost while insufficient power remains, and climbing always needs excess power.'),
  B('Past a certain altitude, the airplane hits the ground regardless of what the pilot does — recognize the trend before that point.'),
  P('Example: a high-altitude, hot-day departure toward rising terrain — the pilot pitches up to hold climb rate, bleeding speed until power required exceeds power available and energy loss becomes irreversible.', 3),
  P('Recovery requires lowering the nose to regain speed at the expense of altitude, and/or turning away from terrain.', 3),
  P('Same trap: an unstable/slow approach, a high-drag go-around, steep pattern turns — or at high speed, a steep spiral or high-speed dive near the ground.', 3),

  S('Conclusion'),
  P('Review: potential plus kinetic energy, the thrust-drag balance, throttle for total energy, elevator for distribution, the 3 rules, total vs distribution errors, irreversible energy loss.'),
  P('The habit: before correcting a deviation, ask whether it\'s total energy or distribution — that tells you whether to reach for the throttle or the elevator.'),
]};

